.evc button,.evc input,.evc select{font:inherit}.evc button,.evc select{-webkit-tap-highlight-color:transparent}.evc button:focus-visible,.evc select:focus-visible,.evc input:focus-visible,.evc a:focus-visible{outline:2px solid color-mix(in srgb,var(--accent) 82%,#fff);outline-offset:2px}
.evc-head{position:relative;z-index:5;display:flex;align-items:center;gap:12px;padding:15px 58px 7px 18px}.evc-heading{min-width:0;display:grid;gap:1px}.evc-heading span{color:var(--accent);font-size:8px;font-weight:780;letter-spacing:.15em}.evc-heading strong{overflow:hidden;font-size:16px;font-weight:690;letter-spacing:-.025em;text-overflow:ellipsis;white-space:nowrap}.evc-value{display:flex;align-items:baseline;margin-left:auto}.evc-value strong{font-size:29px;font-weight:720;letter-spacing:-.06em}.evc-value>span{margin-left:1px;color:var(--muted);font-size:12px;font-weight:680}.evc-value small{margin-left:7px;color:var(--muted);font-size:8px;font-weight:650;letter-spacing:.08em;text-transform:uppercase}.evc-settings{position:absolute;top:14px;right:14px;display:grid;place-items:center;width:34px;height:34px;padding:0;border:1px solid var(--line);border-radius:50%;color:var(--muted);background:var(--soft);cursor:pointer;opacity:.44;transition:opacity .15s ease,transform .15s ease}.evc:hover .evc-settings,.evc-settings:focus-visible{opacity:1}.evc-settings:active{transform:scale(.91)}.evc-settings ha-icon{--mdc-icon-size:17px}
