.evc-flow{position:absolute;z-index:4;left:50%;bottom:9px;width:min(var(--car-width,72%),100%);max-width:100%;height:12px;overflow:hidden;clip-path:inset(0 calc(100% - var(--level)) 0 0 round 999px);pointer-events:none;transform:translateX(-50%)}.evc-flow::before{content:"";position:absolute;top:4px;left:0;width:46px;height:4px;border-radius:999px;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent) 68%,#fff) 48%,#f7fff9 62%,transparent);box-shadow:0 0 8px var(--accent),0 0 15px color-mix(in srgb,var(--accent) 46%,transparent);opacity:0;will-change:transform,opacity}.evc-flow i{position:absolute;top:4px;left:0;width:20px;height:4px;border-radius:999px;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent) 74%,#fff) 35%,#f7fff9 72%,transparent);box-shadow:0 0 7px var(--accent),0 0 13px color-mix(in srgb,var(--accent) 55%,transparent);opacity:0;will-change:transform,opacity}.evc[data-charging="true"] .evc-flow::before{animation:evc-flow-sweep 1.3s cubic-bezier(.4,0,.2,1) infinite}.evc[data-charging="true"] .evc-flow i{animation:evc-current 2.35s cubic-bezier(.4,0,.2,1) infinite;animation-delay:calc(var(--i)*-.47s)}
.evc-target{position:absolute;z-index:5;left:50%;bottom:13px;width:var(--car-width,72%);height:3px;transform:translateX(-50%);pointer-events:none}.evc-target i{position:absolute;left:var(--target);bottom:-4px;width:2px;height:11px;border-radius:2px;background:color-mix(in srgb,var(--ink) 66%,transparent);box-shadow:0 0 0 1px var(--surface);transform:translateX(-1px);transition:left .6s cubic-bezier(.22,1,.36,1)}.evc-target b{position:absolute;left:var(--target);bottom:13px;display:flex;align-items:center;gap:4px;padding:3px 6px;border:1px solid color-mix(in srgb,var(--ink) 15%,transparent);border-radius:7px;color:var(--ink);background:color-mix(in srgb,var(--surface) 94%,transparent);box-shadow:0 5px 14px rgba(0,0,0,.16);font-size:8px;font-weight:760;line-height:1.1;white-space:nowrap;transform:translateX(-50%);transition:left .6s cubic-bezier(.22,1,.36,1)}.evc-target b small{color:var(--muted);font-size:6px;font-weight:760;letter-spacing:.11em}.evc-target b span{font-size:8px;letter-spacing:.02em}.evc[data-reached="true"] .evc-target i{background:var(--accent)}.evc[data-reached="true"] .evc-target b{border-color:color-mix(in srgb,var(--accent) 45%,var(--line));color:var(--accent);animation:evc-target-confirm .42s cubic-bezier(.16,1,.3,1)}.evc[data-reached="true"] .evc-target b::after{content:"✓";font-size:8px}
.evc-car{position:absolute;left:50%;bottom:15px;display:block;width:var(--car-width,72%);height:var(--car-height,82%);transform:translateX(-50%)}.evc-car img{position:absolute;inset:0;width:100%;height:100%;object-fit:fill;pointer-events:none;user-select:none}.evc-car-base{filter:grayscale(1) saturate(0) contrast(.82);opacity:.22}.evc[data-theme="light"] .evc-car-base{filter:grayscale(1) saturate(0) contrast(.65);opacity:.25}.evc-car-live{clip-path:inset(0 calc(100% - var(--level)) 0 0);filter:saturate(1.12) contrast(1.02) drop-shadow(0 14px 14px rgba(0,0,0,.23));transition:clip-path .6s cubic-bezier(.22,1,.36,1)}.evc[data-charging="true"] .evc-car-live{filter:saturate(1.18) contrast(1.03) drop-shadow(0 13px 16px color-mix(in srgb,var(--accent) 22%,rgba(0,0,0,.24)))}
.evc-fallback{position:absolute;inset:0;display:none}.evc-fallback svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}.evc-fallback-base{fill:var(--muted);opacity:.2}.evc-fallback-live{fill:var(--accent);opacity:.86;clip-path:inset(0 calc(100% - var(--level)) 0 0);transition:clip-path .6s cubic-bezier(.22,1,.36,1)}.evc[data-image-error="true"] .evc-car-base,.evc[data-image-error="true"] .evc-car-live{display:none}.evc[data-image-error="true"] .evc-fallback{display:block}
.evc-seam{position:absolute;z-index:6;top:0;bottom:0;left:var(--level);width:2px;background:color-mix(in srgb,var(--accent) 88%,#f7fff9);box-shadow:0 0 12px color-mix(in srgb,var(--accent) 38%,transparent);transition:left .6s cubic-bezier(.22,1,.36,1)}.evc-seam::before,.evc-seam::after{content:"";position:absolute;left:50%;pointer-events:none;opacity:0}.evc-seam::before{inset-block:-3px;width:10px;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent) 34%,transparent),transparent);transform:translateX(-50%) scaleX(.38)}.evc-seam::after{top:-15px;width:5px;height:24px;border-radius:999px;background:linear-gradient(180deg,transparent 0,color-mix(in srgb,var(--accent) 88%,#fff) 42%,#fff 56%,transparent 100%);box-shadow:0 0 6px var(--accent),0 0 13px color-mix(in srgb,var(--accent) 70%,transparent);transform:translate3d(-50%,0,0)}.evc[data-charging="true"] .evc-seam::before{will-change:transform,opacity;animation:evc-seam-field 1.65s cubic-bezier(.65,0,.35,1) infinite}.evc[data-charging="true"] .evc-seam::after{will-change:transform,opacity;animation:evc-seam-spark 1.45s cubic-bezier(.65,0,.35,1) infinite}.evc-seam>i{position:absolute;isolation:isolate;left:50%;bottom:-1px;display:flex;flex-wrap:nowrap;align-items:center;justify-content:center;gap:5px;min-width:64px;height:29px;padding:0 10px;border:1px solid color-mix(in srgb,var(--accent) 78%,#f5fff8);border-radius:10px;color:#06150d;background:var(--accent);box-shadow:0 8px 20px color-mix(in srgb,var(--accent) 30%,rgba(0,0,0,.22));font-style:normal;white-space:nowrap;transform:translate(-50%,50%);transition:transform .35s cubic-bezier(.22,1,.36,1)}.evc[data-level-edge="start"] .evc-seam>i{transform:translate(-10%,50%)}.evc[data-level-edge="end"] .evc-seam>i{transform:translate(-90%,50%)}.evc-seam>i::after{content:"";position:absolute;z-index:-1;inset:-4px;border:1px solid color-mix(in srgb,var(--accent) 72%,transparent);border-radius:13px;opacity:0;will-change:transform,opacity}.evc[data-chargin