.evc-foot{position:relative;z-index:6;display:flex;align-items:center;gap:10px;padding:6px 17px 11px;border-top:1px solid color-mix(in srgb,var(--line) 70%,transparent)}.evc-picker{position:relative;display:grid;grid-template-columns:21px minmax(0,1fr) 16px;align-items:center;gap:5px;width:min(164px,48%);min-width:0;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:11px;color:var(--ink);background:var(--soft)}.evc-picker>ha-icon:first-child{--mdc-icon-size:17px;color:var(--accent)}.evc-picker>ha-icon:last-child{--mdc-icon-size:14px;color:var(--muted)}.evc-picker select{position:absolute;inset:0;z-index:2;width:100%;height:100%;padding:0 29px 0 34px;border:0;outline:0;color:inherit;background:transparent;appearance:none;cursor:pointer;font-size:10px;font-weight:660;text-overflow:ellipsis}.evc-picker select option{color:#17191d;background:#fff}.evc-range{min-width:0;display:grid;grid-template-columns:17px auto;grid-template-areas:"icon value" "icon label";align-items:center;column-gap:5px;color:var(--ink);white-space:nowrap}.evc-range[hidden]{display:none!important}.evc-range>ha-icon{grid-area:icon;--mdc-icon-size:16px;color:var(--accent)}.evc-range>span{grid-area:value;display:flex;align-items:baseline;gap:2px;line-height:1}.evc-range strong{font-size:11px;font-weight:790;letter-spacing:-.02em}.evc-range small{color:var(--ink);font-size:8px;font-weight:720}.evc-range em{grid-area:label;color:var(--muted);font-size:6.5px;font-style:normal;font-weight:720;letter-spacing:.06em;line-height:1.15;text-transform:uppercase}.evc-status{min-width:0;display:flex;align-items:center;gap:6px;margin-left:auto;color:var(--muted);font-size:9px;font-weight:620;white-space:nowrap}.evc-status-dot{position:relative;width:6px;height:6px;border-radius:50%;background:var(--muted)}.evc-status-dot::after{content:"";position:absolute;inset:-4px;border:1px solid var(--accent);border-radius:50%;opacity:0;will-change:transform,opacity}.evc[data-charging="true"] .evc-status-dot{background:var(--accent);box-shadow:0 0 10px color-mix(in srgb,var(--accent) 60%,transparent)}.evc[data-charging="true"] .evc-status-dot::after{animation:evc-status-pulse 1.8s cubic-bezier(.22,1,.36,1) infinite}
.evc-editor{--editor-bg:#1e2227;--editor-surface:#14181c;--editor-ink:#f1f5f3;--editor-muted:#aeb8b4;--editor-line:rgba(241,245,243,.16);position:absolute;z-index:30;inset:0;display:grid;grid-template-rows:auto minmax(0,1fr) auto;color:var(--editor-ink);color-scheme:dark;background:var(--editor-bg);visibility:hidden;transform:translateY(104%);transition:transform .32s cubic-bezier(.22,1,.36,1),visibility 0s linear .32s}.evc[data-theme="light"] .evc-editor{--editor-bg:#f4f6f3;--editor-surface:#fff;--editor-ink:#17201c;--editor-muted:#53605a;--editor-line:rgba(23,32,28,.2);color-scheme:light}.evc-editor.open{visibility:visible;transform:translateY(0);transition-delay:0s}.evc-editor>header{min-height:58px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 15px;border-bottom:1px solid var(--editor-line);background:var(--editor-bg)}.evc-editor>header div{min-width:0;display:grid;gap:2px}.evc-editor>header span{color:var(--accent);font-size:8.5px;font-weight:800;letter-spacing:.14em}.evc-editor>header strong{overflow:hidden;color:var(--editor-ink);font-size:16px;font-weight:740;letter-spacing:-.02em;text-overflow:ellipsis;white-space:nowrap}.evc-editor>header button{display:grid;place-items:center;width:34px;height:34px;padding:0;border:1px solid var(--editor-line);border-radius:50%;color:var(--editor-ink);background:var(--editor-surface);cursor:pointer;transition:transform .15s ease,border-color .15s ease}.evc-editor>header button:hover{border-color:color-mix(in srgb,var(--accent) 55%,var(--editor-line))}.evc-editor>header button:active{transform:scale(.92)}.evc-editor>header ha-icon{--mdc-icon-size:18px}.evc-editor-body{min-width:0;min-height:0;overflow:auto;padding:14px 15px 20px;scrollbar-color:color-mix(in srgb,var(--editor-muted) 46%,transparent) transparent}.evc-editor-body p{margin:0 0 15px;color:var(--editor-muted);font-size:11px;font-weight:520;line-height:1.52;overflow-wrap:anywhere}.evc-editor-body label{min-width:0;display:gri